WITH unpacked AS (SELECT id, service, host, level, context, COALESCE(context['trace'], 'unknown') AS trace_or_default, GET_JSON_OBJECT(payload_json, '$.user.id') AS user_id, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier AS tier, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count FROM app_logs) SELECT *, SUM(retry_count) OVER (PARTITION BY level) AS level_sum_retry_count, ROW_NUMBER() OVER (ORDER BY retry_count DESC, id) AS seq_no, ROW_NUMBER() OVER (ORDER BY retry_count, id) AS row_seq FROM unpacked
